  static const int CKMC_KDF_PRF_HMAC_SHA256 = 1;

  /// < HMAC SHA384
  static const int CKMC_KDF_PRF_HMAC_SHA384 = 2;

  /// < HMAC SHA512
  static const int CKMC_KDF_PRF_HMAC_SHA512 = 3;
}

/// @brief Enumeration for key based key derivation function mode.
